import {
  pgTable,
  pgEnum,
  integer,
  varchar,
  text,
  numeric,
  boolean,
  timestamp,
  jsonb,
  uuid,
  index,
  primaryKey,
  uniqueIndex,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

/**
 * PostgreSQL (Supabase) since October 2026 — docs/data-model.md. Every timestamp is a
 * `timestamptz` read as a `Date`; decimals are `numeric` read as strings; JSON is `jsonb`.
 * Ids are identity columns (`GENERATED BY DEFAULT`), so a copy of old rows keeps its ids and the
 * sequence is moved past them (`scripts/copy-mysql-to-postgres.ts`).
 */
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const id = () => integer('id').primaryKey().generatedByDefaultAsIdentity();

// --- enums: one Postgres type per value set, shared where the values are the same ---------

export const userRole = pgEnum('user_role', ['user', 'admin', 'agent_orders', 'agent_catalog', 'store', 'worker', 'team']);
export const authTokenKind = pgEnum('auth_token_kind', ['verify_email', 'reset_password']);
export const calculationType = pgEnum('calculation_type', [
  'per_m2_floor',
  'per_m2_wall',
  'per_m2_ceiling',
  'per_linear_m',
  'per_unit',
  'per_room',
  'fixed',
]);
export const approvalStatus = pgEnum('approval_status', ['pending', 'approved', 'rejected']);
export const productUnit = pgEnum('product_unit', ['m2', 'linear_m', 'piece', 'liter', 'kg', 'pack', 'set']);
export const model3dStatus = pgEnum('model_3d_status', ['none', 'pending', 'ready', 'failed']);
export const rateKind = pgEnum('rate_kind', ['material', 'labour']);
export const workerPriceUnit = pgEnum('worker_price_unit', ['m2', 'unit', 'fixed']);
export const homeState = pgEnum('home_state', ['old_renovation', 'black_frame', 'white_frame', 'green_frame']);
export const projectStatus = pgEnum('project_status', ['draft', 'saved', 'submitted']);
export const projectMode = pgEnum('project_mode', ['full', 'design_only']);
export const renderStatus = pgEnum('render_status', ['queued', 'processing', 'ready', 'failed']);
/** A project's two halves: what a checkout or a fee is for. */
export const projectHalf = pgEnum('project_half', ['calculator', 'design']);
export const paymentPurpose = pgEnum('payment_purpose', ['calculator', 'design', 'own_item']);
export const paymentStatus = pgEnum('payment_status', ['created', 'processing', 'approved', 'declined', 'expired', 'reversed']);
export const paymentEventSource = pgEnum('payment_event_source', ['callback', 'status']);
export const partnerType = pgEnum('partner_type', ['store', 'worker', 'team']);
export const orderStatus = pgEnum('order_status', ['new', 'confirmed', 'in_progress', 'done', 'cancelled']);
export const orderEventKind = pgEnum('order_event_kind', ['created', 'confirmed', 'status', 'edited', 'message', 'comment']);
/** What a direct upload is for (`lib/uploads/kinds.ts`). */
export const uploadKind = pgEnum('upload_kind', ['image', 'model', 'plan', 'render', 'own_model', 'own_photo']);
export const uploadStatus = pgEnum('upload_status', ['pending', 'consumed']);

export const users = pgTable('users', {
  id: id(),
  name: varchar('name', { length: 255 }).notNull(),
  /** Always lower case: every write lower-cases it and every lookup compares lower case. */
  email: varchar('email', { length: 255 }).notNull().unique(),
  passwordHash: varchar('password_hash', { length: 255 }),
  /**
   * `store`, `worker` and `team` are partner accounts: they see the partner portal, not the
   * admin. `agent_orders` and `agent_catalog` are staff — they see the admin, each with the
   * part of it their job needs (`lib/auth/roles.ts`).
   */
  role: userRole('role').default('user').notNull(),
  /** The store a `store` account manages — its orders, its products. */
  storeId: integer('store_id').references(() => stores.id, { onDelete: 'set null' }),
  /** The worker profile a `worker` account manages. */
  workerId: integer('worker_id').references(() => workers.id, { onDelete: 'set null' }),
  /** The team a `team` account speaks for — its foreman. */
  teamId: integer('team_id').references((): AnyPgColumn => teams.id, { onDelete: 'set null' }),
  /** Set when the address was confirmed by link (or came from Google, which already did). */
  emailVerifiedAt: ts('email_verified_at'),
  /**
   * Admin's switch. A deactivated account cannot sign in, and a session it already has ends at
   * its next request (`lib/auth/accountClaims.ts` re-reads the row) — the row, its projects and
   * its orders stay.
   */
  isActive: boolean('is_active').default(true).notNull(),
  /** The last successful sign-in, password or social. */
  lastLoginAt: ts('last_login_at'),
  /**
   * Raised whenever the password is set anew (a reset, admin's new password): a session signed
   * in under an older value ends at its next request (`refreshSessionToken`), so a reset locks
   * out whoever had the old password and a session made with it.
   */
  sessionVersion: integer('session_version').default(0).notNull(),
  /**
   * The person's own contact, from their profile (`/profile?view=account`) or kept from a
   * checkout ("make it my default address"): a checkout or a booking asks only for what is
   * missing here. The address is the default delivery address — city, street and number,
   * postal code (optional).
   */
  phone: varchar('phone', { length: 50 }),
  addressCity: varchar('address_city', { length: 120 }),
  addressLine: varchar('address_line', { length: 255 }),
  addressPostalCode: varchar('address_postal_code', { length: 20 }),
  createdAt: ts('created_at').defaultNow().notNull(),
}).enableRLS();

/**
 * One-time tokens for e-mail verification and password reset. Only the SHA-256 of the token
 * is stored, so a database leak does not hand out working links; a token is spent on first
 * use and expires on its own.
 */
export const authTokens = pgTable('auth_tokens', {
  id: id(),
  userId: integer('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  kind: authTokenKind('kind').notNull(),
  tokenHash: varchar('token_hash', { length: 64 }).notNull().unique(),
  expiresAt: ts('expires_at').notNull(),
  usedAt: ts('used_at'),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  userKindIdx: index('auth_tokens_user_kind_idx').on(t.userId, t.kind),
})).enableRLS();

/**
 * The catalogue's categories — one tree (`lib/catalog/tree.ts`): each row under its parent,
 * three levels at most, siblings in `sortOrder`. A product sits in one category at any level;
 * a category stands for its whole subtree wherever it is listed.
 */
export const categories = pgTable('categories', {
  id: id(),
  /** The category above; null at the top. A category with children cannot be deleted. */
  parentId: integer('parent_id').references((): AnyPgColumn => categories.id, { onDelete: 'restrict' }),
  nameKa: varchar('name_ka', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }).notNull(),
  nameRu: varchar('name_ru', { length: 255 }),
  slug: varchar('slug', { length: 255 }).notNull().unique(),
  /** A lucide icon's kebab name, or one of the studio's own (`STUDIO_ICONS`). */
  icon: varchar('icon', { length: 100 }),
  calculationType: calculationType('calculation_type').notNull(),
  isVisible: boolean('is_visible').default(true).notNull(),
  isFurniture: boolean('is_furniture').default(false).notNull(),
  /** Offered as a tab in the calculator, with its whole subtree's products. */
  inCalculator: boolean('in_calculator').default(false).notNull(),
  /** The 3D kind whose products belong here: the model pipeline and people's own uploads put them in it. */
  model3dKind: varchar('model_3d_kind', { length: 64 }),
  sortOrder: integer('sort_order').default(0),
}, (t) => ({
  parentIdx: index('categories_parent_idx').on(t.parentId),
})).enableRLS();

/**
 * The studio's rooms — the top row of the furniture shelf (living room, bedroom, …) — made,
 * named, ordered and given icons by admin. Each lists the categories it shows
 * (`shelfRoomCategories`) and the plan's room types it is for: the shelf opens on it when a
 * room of that type is in focus.
 */
export const shelfRooms = pgTable('shelf_rooms', {
  id: id(),
  slug: varchar('slug', { length: 100 }).notNull().unique(),
  nameKa: varchar('name_ka', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }).notNull(),
  nameRu: varchar('name_ru', { length: 255 }),
  icon: varchar('icon', { length: 100 }),
  /** `RoomType`s from `lib/calculator/types`. */
  roomTypes: jsonb('room_types').$type<string[]>(),
  isVisible: boolean('is_visible').default(true).notNull(),
  sortOrder: integer('sort_order').default(0).notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}).enableRLS();

/** Which categories a studio room shows, in its order. A category may be in several rooms. */
export const shelfRoomCategories = pgTable('shelf_room_categories', {
  shelfRoomId: integer('shelf_room_id').notNull().references(() => shelfRooms.id, { onDelete: 'cascade' }),
  categoryId: integer('category_id').notNull().references(() => categories.id, { onDelete: 'cascade' }),
  sortOrder: integer('sort_order').default(0).notNull(),
}, (t) => ({
  pk: primaryKey({ columns: [t.shelfRoomId, t.categoryId] }),
  categoryIdx: index('shelf_room_categories_category_idx').on(t.categoryId),
})).enableRLS();

export const stores = pgTable('stores', {
  id: id(),
  // Unique so the seed's upsert has a key to match on — without it, re-running the seed
  // silently inserted a second copy of every store.
  nameKa: varchar('name_ka', { length: 255 }).notNull().unique(),
  nameEn: varchar('name_en', { length: 255 }),
  nameRu: varchar('name_ru', { length: 255 }),
  logoUrl: varchar('logo_url', { length: 500 }),
  websiteUrl: varchar('website_url', { length: 500 }),
  phone: varchar('phone', { length: 50 }),
  /** Where new orders are announced. Blank means the partner only sees them in the portal. */
  email: varchar('email', { length: 255 }),
  address: varchar('address', { length: 500 }),
  city: varchar('city', { length: 100 }),
  rating: numeric('rating', { precision: 3, scale: 2 }).default('4.50'),
  reviewCount: integer('review_count').default(0),
  deliveryDays: integer('delivery_days').default(3),
  deliveryFeeGel: numeric('delivery_fee_gel', { precision: 8, scale: 2 }).default('0.00'),
  descriptionKa: text('description_ka'),
  descriptionEn: text('description_en'),
  descriptionRu: text('description_ru'),
  /** Platform commission on this store's orders, percent. Null = the platform default. */
  commissionRate: numeric('commission_rate', { precision: 5, scale: 2 }).default('5.00'),
  /**
   * A store that registered itself starts `pending` and is invisible — no products in the
   * catalogue, no store in the sidebar — until admin approves it. Rows admin creates and
   * every row from before self-registration are `approved`.
   */
  approvalStatus: approvalStatus('approval_status').default('approved').notNull(),
  isActive: boolean('is_active').default(true).notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
}).enableRLS();

export const products = pgTable('products', {
  id: id(),
  categoryId: integer('category_id').notNull().references(() => categories.id),
  storeId: integer('store_id').references(() => stores.id),
  /**
   * A piece of furniture a person uploaded for their own flats — a model of their own, or a
   * photo waiting to be made into one. Theirs alone: every public query leaves owned
   * products out, the design catalogue adds the caller's own, and the seeds never touch them.
   */
  ownerUserId: integer('owner_user_id').references(() => users.id, { onDelete: 'cascade' }),
  nameKa: varchar('name_ka', { length: 500 }).notNull(),
  // Translations fall back through en → ka on the client (see `localizedName`).
  nameEn: varchar('name_en', { length: 500 }),
  nameRu: varchar('name_ru', { length: 500 }),
  descriptionKa: text('description_ka'),
  descriptionEn: text('description_en'),
  descriptionRu: text('description_ru'),
  slug: varchar('slug', { length: 500 }).notNull().unique(),
  sku: varchar('sku', { length: 100 }),
  pricePerUnit: numeric('price_per_unit', { precision: 10, scale: 2 }).notNull(),
  unit: productUnit('unit').notNull(),
  coveragePerUnit: numeric('coverage_per_unit', { precision: 10, scale: 4 }),
  brand: varchar('brand', { length: 255 }),
  imageUrl: varchar('image_url', { length: 500 }),
  images: jsonb('images'),
  specs: jsonb('specs'),
  tags: jsonb('tags'),
  /** Style ids this product belongs to, e.g. ['scandinavian','modern']. See lib/design/styles.ts */
  styleTags: jsonb('style_tags'),
  /** Archetype the layout engine places this product as. See ARCHETYPES in lib/design/catalog.ts. */
  model3dKind: varchar('model_3d_kind', { length: 64 }),
  /** Optional GLB. When set, the viewer loads it instead of the procedural mesh. */
  model3dUrl: varchar('model_3d_url', { length: 500 }),
  model3dStatus: model3dStatus('model_3d_status').default('none').notNull(),
  /** Tileable texture for surface products (floor, wall, tile). */
  textureUrl: varchar('texture_url', { length: 500 }),
  /** Dominant colour, used to tint the procedural mesh so it matches the real product. */
  colorHex: varchar('color_hex', { length: 9 }),
  /** Real-world dimensions in cm — drive scale, clearance and collision in autoLayout. */
  widthCm: integer('width_cm'),
  depthCm: integer('depth_cm'),
  heightCm: integer('height_cm'),
  isActive: boolean('is_active').default(true).notNull(),
  isFeatured: boolean('is_featured').default(false).notNull(),
  sortOrder: integer('sort_order').default(0),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}, (t) => ({
  // The public catalogue lists active products by category, featured first; the studio
  // pulls every active product in the design categories. Both filter on these columns.
  activeCategoryIdx: index('products_active_category_idx').on(t.isActive, t.categoryId, t.isFeatured),
  kindIdx: index('products_model3d_kind_idx').on(t.model3dKind),
  ownerIdx: index('products_owner_idx').on(t.ownerUserId),
  storeIdx: index('products_store_idx').on(t.storeId),
})).enableRLS();

/**
 * The calculator's rate book — every per-m² material quantity and labour price the
 * estimate is built from, editable in admin because market prices move faster than code.
 * Seeded from `lib/calculator/constants.ts`; those constants remain the fallback when the
 * table is empty.
 */
export const rates = pgTable('rates', {
  id: id(),
  kind: rateKind('kind').notNull(),
  key: varchar('key', { length: 100 }).notNull().unique(),
  labelKa: varchar('label_ka', { length: 255 }).notNull(),
  phase: integer('phase').notNull(),
  /** Materials: m2 / linear_m / piece / liter / kg / m3. Labour: m2 / unit. */
  unit: varchar('unit', { length: 20 }).notNull(),
  /** Materials only: what the quantity is proportional to. */
  basis: varchar('basis', { length: 20 }),
  qtyPerM2: numeric('qty_per_m2', { precision: 10, scale: 4 }),
  wasteFactorPct: numeric('waste_factor_pct', { precision: 6, scale: 2 }),
  /** Materials: estimated price per unit. Labour: price per m² or per unit. */
  pricePerUnit: numeric('price_per_unit', { precision: 12, scale: 2 }).notNull(),
  linkedCategorySlug: varchar('linked_category_slug', { length: 100 }),
  sortOrder: integer('sort_order').default(0).notNull(),
  isActive: boolean('is_active').default(true).notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}).enableRLS();

export type Rate = typeof rates.$inferSelect;

export const workers = pgTable('workers', {
  id: id(),
  nameKa: varchar('name_ka', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }),
  nameRu: varchar('name_ru', { length: 255 }),
  specialty: varchar('specialty', { length: 255 }).notNull(),
  specialtySlug: varchar('specialty_slug', { length: 100 }).notNull(),
  phone: varchar('phone', { length: 50 }),
  /** Where new bookings are announced. */
  email: varchar('email', { length: 255 }),
  /** Platform commission on this worker's bookings, percent. Null = the platform default. */
  commissionRate: numeric('commission_rate', { precision: 5, scale: 2 }).default('5.00'),
  pricePerM2: numeric('price_per_m2', { precision: 8, scale: 2 }),
  pricePerUnit: numeric('price_per_unit', { precision: 8, scale: 2 }),
  priceUnit: workerPriceUnit('price_unit').notNull(),
  rating: numeric('rating', { precision: 3, scale: 2 }).default('5.00'),
  reviewCount: integer('review_count').default(0),
  bio: text('bio'),
  bioEn: text('bio_en'),
  bioRu: text('bio_ru'),
  avatarUrl: varchar('avatar_url', { length: 500 }),
  city: varchar('city', { length: 100 }),
  experienceYears: integer('experience_years'),
  completedJobs: integer('completed_jobs').default(0),
  isVerified: boolean('is_verified').default(false).notNull(),
  /** Self-registered workers wait here (`pending`, inactive) until admin approves them. */
  approvalStatus: approvalStatus('approval_status').default('approved').notNull(),
  isActive: boolean('is_active').default(true).notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  activeSpecialtyIdx: index('workers_active_specialty_idx').on(t.isActive, t.specialtySlug),
})).enableRLS();

/** A client's review of a worker; `workers.rating` / `reviewCount` are kept as aggregates. */
/**
 * A brigade — ბრიგადა — the unit a Georgian renovation is actually hired as.
 *
 * Nobody books a tiler, then an electrician, then a plasterer and hopes the dates line up:
 * they hire a team that already has all of them and a foreman who answers the phone. A team
 * is therefore the partner a whole job is sent to, beside the stores that supply it, and the
 * trades it covers come from the workers in it (`team_members`).
 */
export const teams = pgTable('teams', {
  id: id(),
  nameKa: varchar('name_ka', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }),
  nameRu: varchar('name_ru', { length: 255 }),
  slug: varchar('slug', { length: 255 }).notNull().unique(),
  descriptionKa: text('description_ka'),
  descriptionEn: text('description_en'),
  descriptionRu: text('description_ru'),
  /** The foreman — who the customer talks to. */
  leadName: varchar('lead_name', { length: 255 }),
  phone: varchar('phone', { length: 50 }),
  /** Where a job sent to the team is announced. */
  email: varchar('email', { length: 255 }),
  logoUrl: varchar('logo_url', { length: 500 }),
  city: varchar('city', { length: 100 }),
  rating: numeric('rating', { precision: 3, scale: 2 }).default('5.00'),
  reviewCount: integer('review_count').default(0),
  completedJobs: integer('completed_jobs').default(0),
  experienceYears: integer('experience_years'),
  /** What the team charges over the trades' own rates, percent; null = nothing. */
  markupPct: numeric('markup_pct', { precision: 5, scale: 2 }),
  /** Platform commission on this team's jobs, percent. Null = the platform default. */
  commissionRate: numeric('commission_rate', { precision: 5, scale: 2 }).default('5.00'),
  /** How much work the team can take on at once; the directory says who is free. */
  capacityJobs: integer('capacity_jobs').default(1),
  isVerified: boolean('is_verified').default(false).notNull(),
  /** Self-registered teams wait here (`pending`, inactive) until admin approves them. */
  approvalStatus: approvalStatus('approval_status').default('approved').notNull(),
  isActive: boolean('is_active').default(true).notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  activeCityIdx: index('teams_active_city_idx').on(t.isActive, t.city),
})).enableRLS();

/** Which workers a team is made of; the trades it covers are theirs. */
export const teamMembers = pgTable('team_members', {
  id: id(),
  teamId: integer('team_id').notNull().references(() => teams.id, { onDelete: 'cascade' }),
  workerId: integer('worker_id').notNull().references(() => workers.id, { onDelete: 'cascade' }),
  /** The foreman, who answers for the job. */
  isLead: boolean('is_lead').default(false).notNull(),
  sortOrder: integer('sort_order').default(0).notNull(),
}, (t) => ({
  teamIdx: index('team_members_team_idx').on(t.teamId),
  workerIdx: index('team_members_worker_idx').on(t.workerId),
})).enableRLS();

export const workerReviews = pgTable('worker_reviews', {
  id: id(),
  workerId: integer('worker_id').notNull().references(() => workers.id, { onDelete: 'cascade' }),
  authorName: varchar('author_name', { length: 255 }).notNull(),
  rating: integer('rating').notNull(),
  textKa: text('text_ka'),
  textEn: text('text_en'),
  textRu: text('text_ru'),
  /** What the job was, e.g. "bathroom tiling, 8 m²". */
  jobKa: varchar('job_ka', { length: 255 }),
  jobEn: varchar('job_en', { length: 255 }),
  jobRu: varchar('job_ru', { length: 255 }),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  workerIdx: index('worker_reviews_worker_idx').on(t.workerId, t.createdAt),
})).enableRLS();

/** One finished job in a worker's portfolio. */
export const workerWorks = pgTable('worker_works', {
  id: id(),
  workerId: integer('worker_id').notNull().references(() => workers.id, { onDelete: 'cascade' }),
  titleKa: varchar('title_ka', { length: 255 }).notNull(),
  titleEn: varchar('title_en', { length: 255 }),
  titleRu: varchar('title_ru', { length: 255 }),
  descriptionKa: text('description_ka'),
  descriptionEn: text('description_en'),
  descriptionRu: text('description_ru'),
  imageUrl: varchar('image_url', { length: 500 }),
  areaM2: numeric('area_m2', { precision: 8, scale: 2 }),
  city: varchar('city', { length: 100 }),
  year: integer('year'),
  sortOrder: integer('sort_order').default(0).notNull(),
}, (t) => ({
  workerIdx: index('worker_works_worker_idx').on(t.workerId, t.sortOrder),
})).enableRLS();

export const projects = pgTable('projects', {
  id: id(),
  userId: integer('user_id').references(() => users.id),
  sessionId: varchar('session_id', { length: 255 }),
  nameKa: varchar('name_ka', { length: 255 }).default('ჩემი პროექტი'),
  /**
   * The home's condition. NULL until it is chosen: a project is created, named, before its
   * first step (`POST /api/projects/create`), and the calculator asks for the condition there.
   */
  homeState: homeState('home_state'),
  totalM2: numeric('total_m2', { precision: 8, scale: 2 }).notNull(),
  rooms: jsonb('rooms').notNull(),
  selectedProducts: jsonb('selected_products'),
  selectedFurniture: jsonb('selected_furniture'),
  /**
   * What the person made of the calculator's estimate on its summary: `{ excluded, quantities }`
   * by line key (`lib/design/ticks`). The estimate itself is never stored — it is worked out
   * again from the rooms and the picks — so this is all that is needed to show the original
   * beside the edit. The design half keeps its own in `scene`.
   */
  calculatorEdits: jsonb('calculator_edits'),
  /**
   * The calculator's own drawing board, `{ plan, floorPlanUrl, finishes }`: the walls, doors and
   * windows drawn on its plan step and the finishes laid on its placement step. Not `plan` —
   * `plan IS NOT NULL` is what says a project has a 3D design.
   */
  calculatorBoard: jsonb('calculator_board'),
  /**
   * How many times each half has been written. A save names the revision it was made from
   * and is refused (409) when the row has moved on — another tab, another computer — instead
   * of writing an older copy over a newer one; the browser's cache of a half is current when
   * it is at the row's revision (`lib/flow/projectSync`). A rename or an order is neither.
   */
  calculatorRev: integer('calculator_rev').default(0).notNull(),
  designRev: integer('design_rev').default(0).notNull(),
  /**
   * The id of the last save of each half (made by the browser). A save whose answer never
   * arrived — a dropped connection, a reload mid-write — still moved the revision on; the next
   * save from that browser names it, and is recognised as following its own write rather than
   * refused as a conflict with somebody else's.
   */
  calculatorSaveId: varchar('calculator_save_id', { length: 36 }),
  designSaveId: varchar('design_save_id', { length: 36 }),
  totalMaterialsCost: numeric('total_materials_cost', { precision: 12, scale: 2 }),
  totalFurnitureCost: numeric('total_furniture_cost', { precision: 12, scale: 2 }),
  totalWorkersCost: numeric('total_workers_cost', { precision: 12, scale: 2 }),
  totalCost: numeric('total_cost', { precision: 12, scale: 2 }),
  status: projectStatus('status').default('draft'),
  /** 'full' = renovation + design, 'design_only' = interior design of a finished home. */
  mode: projectMode('mode').default('full').notNull(),
  /** Chosen interior style id. See lib/design/styles.ts */
  styleId: varchar('style_id', { length: 32 }),
  budgetGel: numeric('budget_gel', { precision: 12, scale: 2 }),
  /** Uploaded 2D floor plan image. */
  floorPlanUrl: varchar('floor_plan_url', { length: 500 }),
  /** Parsed FloorPlan (rooms as polygons + openings + scale). See lib/design/types.ts */
  plan: jsonb('plan'),
  /** DesignScene — surface finishes and furniture placements. See lib/design/types.ts */
  scene: jsonb('scene'),
  /** DesignVersion[] — the kept versions of the flat (version 01 is the existing house). */
  versions: jsonb('versions'),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}, (t) => ({
  // Profile and admin lists: a user's projects, newest first.
  userCreatedIdx: index('projects_user_created_idx').on(t.userId, t.createdAt),
})).enableRLS();

/**
 * A photo taken in the studio and the realistic render requested from it.
 *
 * `sourceUrl` is the studio's own screenshot, stored the moment the user asks for a render
 * and downloadable at once; `renderUrl` is filled in when the render is produced (by hand
 * or by an image model — there is no generator wired in yet, so rows wait in `queued`).
 * `camera` keeps the view so the render can be redone from the same spot.
 */
export const projectRenders = pgTable('project_renders', {
  id: id(),
  projectId: integer('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  sourceUrl: varchar('source_url', { length: 500 }).notNull(),
  renderUrl: varchar('render_url', { length: 500 }),
  status: renderStatus('status').default('queued').notNull(),
  /** Room in focus when the photo was taken, if any. */
  roomName: varchar('room_name', { length: 255 }),
  camera: jsonb('camera'),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}, (t) => ({
  projectIdx: index('project_renders_project_idx').on(t.projectId, t.createdAt),
})).enableRLS();

// ---------------------------------------------------------------------------
// Marketplace: platform fees, partner orders and commissions
// ---------------------------------------------------------------------------

/**
 * One row. What the platform charges: a fee per square metre for a calculation and for a
 * 3D design (paid before the half's hinge — `project_payments`), and the default commission on
 * partner stores and workers. A store or worker with its own `commissionRate` overrides the
 * default.
 */
export const platformSettings = pgTable('platform_settings', {
  id: id(),
  calculatorFeePerM2: numeric('calculator_fee_per_m2', { precision: 8, scale: 2 }).default('2.00').notNull(),
  designFeePerM2: numeric('design_fee_per_m2', { precision: 8, scale: 2 }).default('12.00').notNull(),
  storeCommissionPct: numeric('store_commission_pct', { precision: 5, scale: 2 }).default('5.00').notNull(),
  workerCommissionPct: numeric('worker_commission_pct', { precision: 5, scale: 2 }).default('5.00').notNull(),
  /** GEL for adding a piece of one's own furniture as a 3D model ("ჩემი ნივთის დამატება"); 0 = free. */
  ownItemPrice: numeric('own_item_price', { precision: 8, scale: 2 }).default('10.00').notNull(),
  /**
   * The bank's commission on a card payment, percent, added on top of whatever is paid and
   * shown to the person as a line of its own (Flitt's GEL card rate is 2.2 %).
   */
  bankFeePct: numeric('bank_fee_pct', { precision: 5, scale: 2 }).default('2.20').notNull(),
  /**
   * The store that supplies the construction materials of the rate book (blocks, plaster,
   * putty, pipes, cable…): a checkout sends the project's material lines to it as an order of
   * their own. NULL = nobody, and those lines are reported as unassigned.
   */
  materialsStoreId: integer('materials_store_id').references(() => stores.id, { onDelete: 'set null' }),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}).enableRLS();

/**
 * A customer placing the order for a whole project: one partner `order` per store the goods
 * come from, and where they go. Totals are snapshots — what was ordered the day it was placed.
 * The platform's fee is paid before the half's hinge now (`project_payments`); `platformFee` is
 * 0 on every checkout since, and holds the fee only on those placed before.
 */
export const checkouts = pgTable('checkouts', {
  id: id(),
  projectId: integer('project_id').references(() => projects.id, { onDelete: 'set null' }),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  kind: projectHalf('kind').notNull(),
  totalM2: numeric('total_m2', { precision: 8, scale: 2 }).notNull(),
  feePerM2: numeric('fee_per_m2', { precision: 8, scale: 2 }).notNull(),
  platformFee: numeric('platform_fee', { precision: 12, scale: 2 }).notNull(),
  goodsTotal: numeric('goods_total', { precision: 12, scale: 2 }).notNull(),
  commissionTotal: numeric('commission_total', { precision: 12, scale: 2 }).notNull(),
  customerName: varchar('customer_name', { length: 255 }).notNull(),
  customerPhone: varchar('customer_phone', { length: 50 }).notNull(),
  customerEmail: varchar('customer_email', { length: 255 }),
  note: text('note'),
  /** Where the goods go (the stores deliver there): the account's default address or one given at checkout. */
  deliveryCity: varchar('delivery_city', { length: 120 }),
  deliveryAddress: varchar('delivery_address', { length: 255 }),
  deliveryPostalCode: varchar('delivery_postal_code', { length: 20 }),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  createdIdx: index('checkouts_created_idx').on(t.createdAt),
  userIdx: index('checkouts_user_idx').on(t.userId),
})).enableRLS();

/**
 * The platform's fee for one half of a project, paid before the half's hinge — "გამოთვლის
 * დაწყება" in the calculator, the generation in the studio (`HingeDialog`): the half's floor area
 * × the fee per m² of the day. One row per half (a half is paid once), written when the half's
 * Flitt payment (`payments`) is approved — `method` `flitt`, `reference` the Flitt order id;
 * rows from before the provider have `method` `test`. `amount` is the platform's fee alone: the
 * bank's commission paid on top is on the `payments` row. The row is the record the revenue
 * report counts. A checkout charges no fee any more — only fees recorded before this table
 * existed are on `checkouts`.
 */
export const projectPayments = pgTable('project_payments', {
  id: id(),
  projectId: integer('project_id').references(() => projects.id, { onDelete: 'set null' }),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  kind: projectHalf('kind').notNull(),
  totalM2: numeric('total_m2', { precision: 8, scale: 2 }).notNull(),
  feePerM2: numeric('fee_per_m2', { precision: 8, scale: 2 }).notNull(),
  amount: numeric('amount', { precision: 12, scale: 2 }).notNull(),
  /** How it was paid: `flitt`, or `test` for the stand-in card form before the provider. */
  method: varchar('method', { length: 20 }).default('test').notNull(),
  cardLast4: varchar('card_last4', { length: 4 }),
  /** The payment's own reference: the Flitt order id (`payments.orderId`), made up for a test one. */
  reference: varchar('reference', { length: 64 }).notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  projectKindIdx: uniqueIndex('project_payments_project_kind_idx').on(t.projectId, t.kind),
  createdIdx: index('project_payments_created_idx').on(t.createdAt),
})).enableRLS();

/**
 * One payment through Flitt (docs/payments.md): a half's fee before its hinge, or the price of
 * adding a piece of one's own furniture. Made when the payment dialogue asks Flitt for a
 * checkout token (`status` `created`), settled by Flitt's signed answer — its callback, or the
 * status the server asks for once the embedded form says it is done. `orderId` is what Flitt
 * knows it by. The money: `amount` is the price itself (the fee, the item), `bankFee` the
 * bank's commission at `bankFeePct` added on top, `total` what the card is charged.
 *
 * An approved half writes its `project_payments` row; an approved `own_item` is a credit the
 * next upload uses up (`consumedAt`, then `productId`), so a payment whose upload failed is
 * not lost.
 */
export const payments = pgTable('payments', {
  id: id(),
  orderId: varchar('order_id', { length: 64 }).notNull().unique(),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  purpose: paymentPurpose('purpose').notNull(),
  projectId: integer('project_id').references(() => projects.id, { onDelete: 'set null' }),
  /** The own item this payment was spent on. */
  productId: integer('product_id').references(() => products.id, { onDelete: 'set null' }),
  /** A half's quote as it was charged: the area and the rate. */
  totalM2: numeric('total_m2', { precision: 8, scale: 2 }),
  feePerM2: numeric('fee_per_m2', { precision: 8, scale: 2 }),
  amount: numeric('amount', { precision: 12, scale: 2 }).notNull(),
  bankFeePct: numeric('bank_fee_pct', { precision: 5, scale: 2 }).default('0.00').notNull(),
  bankFee: numeric('bank_fee', { precision: 12, scale: 2 }).default('0.00').notNull(),
  total: numeric('total', { precision: 12, scale: 2 }).notNull(),
  currency: varchar('currency', { length: 3 }).default('GEL').notNull(),
  /** Flitt's `order_status`, as last heard. Only `approved` unlocks anything. */
  status: paymentStatus('status').default('created').notNull(),
  provider: varchar('provider', { length: 20 }).default('flitt').notNull(),
  /** Made against a merchant in test mode: no money moved. */
  testMode: boolean('test_mode').default(true).notNull(),
  /** Flitt's own id for the payment (`payment_id`). */
  providerPaymentId: varchar('provider_payment_id', { length: 32 }),
  /** What Flitt last said about the card and the money (`payment_events` keeps every answer whole). */
  maskedCard: varchar('masked_card', { length: 19 }),
  cardType: varchar('card_type', { length: 20 }),
  cardBin: varchar('card_bin', { length: 8 }),
  /** How it was paid: `card`, or a wallet (`additional_info.payment_method`: `googlepay`, `apple`). */
  paymentSystem: varchar('payment_system', { length: 30 }),
  /** What was taken from the card, and what has been given back since — GEL, from Flitt's tetri. */
  actualAmount: numeric('actual_amount', { precision: 12, scale: 2 }),
  actualCurrency: varchar('actual_currency', { length: 3 }),
  reversalAmount: numeric('reversal_amount', { precision: 12, scale: 2 }).default('0.00').notNull(),
  /** The bank's reference and authorisation code, for a dispute or a refund. */
  rrn: varchar('rrn', { length: 50 }),
  approvalCode: varchar('approval_code', { length: 16 }),
  /** Flitt's own time of the order, as it writes it (`DD.MM.YYYY hh:mm:ss`, Tbilisi). */
  orderTime: varchar('order_time', { length: 19 }),
  /** A decline's code and words, as Flitt gave them. */
  responseCode: varchar('response_code', { length: 16 }),
  responseDescription: varchar('response_description', { length: 255 }),
  /** When Flitt last answered about it (a callback or a status). */
  lastEventAt: ts('last_event_at'),
  paidAt: ts('paid_at'),
  /** When an own item's credit was claimed by an upload. */
  consumedAt: ts('consumed_at'),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}, (t) => ({
  userPurposeIdx: index('payments_user_purpose_idx').on(t.userId, t.purpose, t.status),
  projectIdx: index('payments_project_idx').on(t.projectId),
  createdIdx: index('payments_created_idx').on(t.createdAt),
})).enableRLS();

/**
 * Every answer Flitt gave about a payment, whole — each callback and each status the server
 * asked for — so the admin's transaction page can show exactly what was received
 * (docs/payments.md). The payload is Flitt's parameters as they came, less the test mode's
 * signing hint; `signatureValid` false is a callback that failed its signature (only kept when
 * it names an order of ours) and changed nothing.
 */
export const paymentEvents = pgTable('payment_events', {
  id: id(),
  paymentId: integer('payment_id').references(() => payments.id, { onDelete: 'cascade' }),
  orderId: varchar('order_id', { length: 64 }).notNull(),
  source: paymentEventSource('source').notNull(),
  signatureValid: boolean('signature_valid').notNull(),
  orderStatus: varchar('order_status', { length: 20 }),
  payload: jsonb('payload').$type<Record<string, unknown>>().notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  paymentIdx: index('payment_events_payment_idx').on(t.paymentId, t.createdAt),
})).enableRLS();

/**
 * What one partner has to fulfil: a store's part of a checkout, or a worker's booking.
 * `subtotal` is the sum of the active items and is recomputed whenever the partner edits
 * them; `commissionPct` is frozen at creation so a later rate change does not rewrite
 * history. Cancelled orders earn nothing.
 */
export const orders = pgTable('orders', {
  id: id(),
  checkoutId: integer('checkout_id').references(() => checkouts.id, { onDelete: 'set null' }),
  projectId: integer('project_id').references(() => projects.id, { onDelete: 'set null' }),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  partnerType: partnerType('partner_type').notNull(),
  storeId: integer('store_id').references(() => stores.id, { onDelete: 'set null' }),
  workerId: integer('worker_id').references(() => workers.id, { onDelete: 'set null' }),
  teamId: integer('team_id').references(() => teams.id, { onDelete: 'set null' }),
  status: orderStatus('status').default('new').notNull(),
  subtotal: numeric('subtotal', { precision: 12, scale: 2 }).default('0.00').notNull(),
  deliveryFee: numeric('delivery_fee', { precision: 10, scale: 2 }).default('0.00').notNull(),
  commissionPct: numeric('commission_pct', { precision: 5, scale: 2 }).default('5.00').notNull(),
  commissionAmount: numeric('commission_amount', { precision: 12, scale: 2 }).default('0.00').notNull(),
  customerName: varchar('customer_name', { length: 255 }).notNull(),
  customerPhone: varchar('customer_phone', { length: 50 }).notNull(),
  customerEmail: varchar('customer_email', { length: 255 }),
  /** What the customer wrote at checkout. */
  customerNote: text('customer_note'),
  /** Where the partner delivers or works: the checkout's (or the booking's) address, copied onto each order. */
  deliveryCity: varchar('delivery_city', { length: 120 }),
  deliveryAddress: varchar('delivery_address', { length: 255 }),
  deliveryPostalCode: varchar('delivery_postal_code', { length: 20 }),
  /** What the partner wrote back — delivery date, a substitution, a question. */
  partnerMessage: text('partner_message'),
  /**
   * The agent's own note: what they checked, who they rang, what they changed and why. It
   * belongs to the platform, not to the customer or the partner, and neither of them sees it.
   */
  staffNote: text('staff_note'),
  /** First time the partner opened it; null = unread badge. */
  viewedAt: ts('viewed_at'),
  /**
   * When the partner was given the order. A store's order waits for the platform first: the
   * orders agent checks it with the customer (lines kept or struck, delivery) and confirms it,
   * and only then does the store see it. A brigade's or a worker's booking is sent at once.
   * NULL = still with the platform; the partner portal shows only orders that have one.
   */
  sentAt: ts('sent_at'),
  /** When the platform confirmed a store's order, and who did. */
  confirmedAt: ts('confirmed_at'),
  confirmedBy: integer('confirmed_by').references(() => users.id, { onDelete: 'set null' }),
  /** The delivery fee as the order was placed, so a change the agent makes shows as one. */
  originalDeliveryFee: numeric('original_delivery_fee', { precision: 10, scale: 2 }),
  createdAt: ts('created_at').defaultNow().notNull(),
  updatedAt: ts('updated_at').defaultNow().$onUpdate(() => new Date()).notNull(),
}, (t) => ({
  storeCreatedIdx: index('orders_store_created_idx').on(t.storeId, t.createdAt),
  workerCreatedIdx: index('orders_worker_created_idx').on(t.workerId, t.createdAt),
  teamCreatedIdx: index('orders_team_created_idx').on(t.teamId, t.createdAt),
  statusIdx: index('orders_status_idx').on(t.status),
  createdIdx: index('orders_created_idx').on(t.createdAt),
  checkoutIdx: index('orders_checkout_idx').on(t.checkoutId),
})).enableRLS();

/**
 * A line of an order. Names are snapshots so a renamed or deleted product still reads
 * correctly; `removed` keeps a line the partner struck out visible (and out of the totals)
 * instead of deleting it, so the customer can see what changed.
 */
export const orderItems = pgTable('order_items', {
  id: id(),
  orderId: integer('order_id').notNull().references(() => orders.id, { onDelete: 'cascade' }),
  productId: integer('product_id').references(() => products.id, { onDelete: 'set null' }),
  nameKa: varchar('name_ka', { length: 500 }).notNull(),
  nameEn: varchar('name_en', { length: 500 }),
  nameRu: varchar('name_ru', { length: 500 }),
  categorySlug: varchar('category_slug', { length: 100 }),
  roomName: varchar('room_name', { length: 255 }),
  unit: varchar('unit', { length: 20 }).default('piece').notNull(),
  qty: numeric('qty', { precision: 10, scale: 2 }).notNull(),
  unitPrice: numeric('unit_price', { precision: 12, scale: 2 }).notNull(),
  total: numeric('total', { precision: 12, scale: 2 }).notNull(),
  removed: boolean('removed').default(false).notNull(),
  note: text('note'),
  sortOrder: integer('sort_order').default(0).notNull(),
  /**
   * The quantity and price the line was ordered at. The customer's view shows every change
   * against them ("3 → 2"); NULL on a line added afterwards, which is how an added line is told.
   */
  originalQty: numeric('original_qty', { precision: 10, scale: 2 }),
  originalUnitPrice: numeric('original_unit_price', { precision: 12, scale: 2 }),
}, (t) => ({
  orderIdx: index('order_items_order_idx').on(t.orderId),
  productIdx: index('order_items_product_idx').on(t.productId),
})).enableRLS();

/**
 * What happened to an order and what was said about it: its creation, the platform's
 * confirmation, status changes, edits of its lines and delivery, the message to the customer —
 * and the comments the platform's people and the partner leave for each other. Never shown to
 * the customer; the partner sees the whole thread except the staff's own note (which is not an
 * event at all).
 */
export const orderEvents = pgTable('order_events', {
  id: id(),
  orderId: integer('order_id').notNull().references(() => orders.id, { onDelete: 'cascade' }),
  userId: integer('user_id').references(() => users.id, { onDelete: 'set null' }),
  /** The author's role when they wrote it, and their name — the thread outlives role changes. */
  actorRole: varchar('actor_role', { length: 20 }),
  actorName: varchar('actor_name', { length: 255 }),
  kind: orderEventKind('kind').notNull(),
  /** A comment's or a message's text. */
  body: text('body'),
  /** The facts of a system event: `{ from, to }` for a status, counts for an edit. */
  meta: jsonb('meta'),
  createdAt: ts('created_at').defaultNow().notNull(),
}, (t) => ({
  orderIdx: index('order_events_order_idx').on(t.orderId, t.createdAt),
})).enableRLS();

// ---------------------------------------------------------------------------
// Platform plumbing: shared counters and direct uploads
// ---------------------------------------------------------------------------

/**
 * The request counters every server instance shares (`lib/api/rateLimit.ts`): a fixed window per
 * key — `<rule>:<client address>` for the per-IP limits, `login-fail:<e-mail>` for the account
 * lockout (`lib/auth/lockout.ts`, which also sets `lockedUntil`). On Vercel each request may land
 * on a different instance, so a count kept in memory counted nothing. Rows whose window has
 * passed are swept by the daily cleanup (`/api/cron/cleanup`).
 */
export const rateLimits = pgTable('rate_limits', {
  key: varchar('key', { length: 255 }).primaryKey(),
  windowStart: ts('window_start').notNull(),
  count: integer('count').default(0).notNull(),
  /** The previous window's count, for the sliding estimate (`lib/api/rateLimit.ts`). */
  prevCount: integer('prev_count').default(0).notNull(),
  lockedUntil: ts('locked_until'),
}, (t) => ({
  windowIdx: index('rate_limits_window_idx').on(t.windowStart),
})).enableRLS();

/**
 * A file on its way in (docs/uploads.md). The browser asks for a place to put a file
 * (`POST /api/uploads`): a row is made here, with the kind, who asked and the most it may weigh,
 * and the browser sends the bytes straight to storage — the private staging bucket under
 * `stagingKey` — never through a function. The route the file is for then claims the row by its
 * id (`claimUpload`): only once, only by whoever made it, only before `expiresAt`; it reads the
 * staged bytes, checks their real size and what they really are, and publishes the result.
 */
export const uploads = pgTable('uploads', {
  id: uuid('id').primaryKey().defaultRandom(),
  kind: uploadKind('kind').notNull(),
  /** Who asked; null for a visitor's floor plan (the one kind open to them). */
  userId: integer('user_id').references(() => users.id, { onDelete: 'cascade' }),
  /** Where the bytes were sent: a key in the staging bucket, made by the server. */
  stagingKey: varchar('staging_key', { length: 255 }).notNull().unique(),
  maxBytes: integer('max_bytes').notNull(),
  /** What the browser said the file is: kept for the log, never trusted. */
  declaredType: varchar('declared_type', { length: 100 }),
  declaredSize: integer('declared_size'),
  status: uploadStatus('status').default('pending').notNull(),
  createdAt: ts('created_at').defaultNow().notNull(),
  expiresAt: ts('expires_at').notNull(),
  consumedAt: ts('consumed_at'),
}, (t) => ({
  createdIdx: index('uploads_created_idx').on(t.createdAt),
  userIdx: index('uploads_user_idx').on(t.userId),
})).enableRLS();

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type ShelfRoomRow = typeof shelfRooms.$inferSelect;
export type Store = typeof stores.$inferSelect;
export type NewStore = typeof stores.$inferInsert;
export type Product = typeof products.$inferSelect;
export type NewProduct = typeof products.$inferInsert;
export type Worker = typeof workers.$inferSelect;
export type NewWorker = typeof workers.$inferInsert;
export type WorkerReview = typeof workerReviews.$inferSelect;
export type WorkerWork = typeof workerWorks.$inferSelect;
export type Project = typeof projects.$inferSelect;
export type ProjectPayment = typeof projectPayments.$inferSelect;
export type Payment = typeof payments.$inferSelect;
export type PaymentEvent = typeof paymentEvents.$inferSelect;
export type NewProject = typeof projects.$inferInsert;
export type ProjectRender = typeof projectRenders.$inferSelect;
export type ApprovalStatus = Store['approvalStatus'];
export type PlatformSettingsRow = typeof platformSettings.$inferSelect;
export type Checkout = typeof checkouts.$inferSelect;
export type Order = typeof orders.$inferSelect;
export type NewOrder = typeof orders.$inferInsert;
export type OrderItem = typeof orderItems.$inferSelect;
export type NewOrderItem = typeof orderItems.$inferInsert;
export type OrderEvent = typeof orderEvents.$inferSelect;
export type OrderStatus = Order['status'];
export type UserRole = User['role'];
export type Team = typeof teams.$inferSelect;
export type NewTeam = typeof teams.$inferInsert;
export type TeamMember = typeof teamMembers.$inferSelect;
export type UploadRow = typeof uploads.$inferSelect;
export type UploadKind = UploadRow['kind'];
